+/** A parsed version: [major, minor, patch]. */
+type Tri = [number, number, number];
+
+/** A parsed partial version: numbers, with `null` for a wildcard or an omitted part. */
+type Partial3 = [number | null, number | null, number | null];
+
+type Predicate = (v: Tri) => boolean;
+
+const FULL_VERSION = /^(\d+)\.(\d+)\.(\d+)$/;
+const COMPARATOR = /^(<=|>=|<|>|=|~|\^)?(.*)$/s;
+
+function invalid(what: string, text: string): Error {
+  return new Error(`Invalid ${what}: "${text}"`);
+}
+
+function parseVersion(text: string): Tri {
+  const m = FULL_VERSION.exec(text);
+  if (!m) throw invalid("version", text);
+  return [Number(m[1]), Number(m[2]), Number(m[3])];
+}
+
+/** Parses a possibly partial version such as `1`, `1.2`, `1.x` or `*`. */
+function parsePartial(text: string): Partial3 {
+  const parts = text.split(".");
+  if (parts.length > 3) throw invalid("version", text);
+  const result: Partial3 = [null, null, null];
+  let wildcard = false;
+  for (let i = 0; i < 3; i++) {
+    const part = parts[i];
+    if (part === undefined || /^[xX*]$/.test(part)) {
+      wildcard = true;
+      continue;
+    }
+    if (!/^\d+$/.test(part) || wildcard) throw invalid("version", text);
+    result[i] = Number(part);
+  }
+  return result;
+}
+
+function compare(a: Tri, b: Tri): number {
+  for (let i = 0; i < 3; i++) {
+    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
+  }
+  return 0;
+}
